<?php declare(strict_types=1); class TaxonomyMediaService extends MediaService{public function storeTaxonomy(array$file,string$type,int$id):array{$validation=$this->validate($file);$dir=AppConfig::$data['uploads'].'/taxonomies/'.$type.'/'.$id;if(!is_dir($dir))mkdir($dir,0750,true);$name='taxonomy_'.$id.'_'.bin2hex(random_bytes(8)).'.'.$validation[1];if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$name))throw new RuntimeException('No fue posible guardar la imagen.');return['path'=>'uploads/taxonomies/'.$type.'/'.$id.'/'.$name];}}
